rovided'=>'無効なダウンロードURLが提供されました','Download URL must use HTTP or HTTPS protocol'=>'ダウンロードURLはHTTPまたはHTTPSプロトコルを使用する必要があります','Download URL is not from an allowed domain: %s'=>'ダウンロードURLは許可されたドメインからではありません: %s','Could not create a temporary package file'=>'一時的なパッケージファイルを作成できませんでした','Failed to download plugin: %s'=>'プラグインのダウンロードに失敗しました: %s','The plugin package download failed'=>'プラグインパッケージのダウンロードに失敗しました','Failed to get plugin information: %s'=>'プラグイン情報の取得に失敗しました: %s','MCP Adapter could not be installed or activated. Use the plugin page or contact your host.'=>'MCPアダプターをインストールまたは有効化できませんでした。プラグインページを使用するか、ホストに連絡してください。','MCP Adapter activated.'=>'MCPアダプターが有効化されました。','ERR'=>'ERR']];